73: String md5Utils::base64ToHex(String base64Hash) {
74:     // Base64 decoding map
75:     const char base64Table[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
76:     int base64Value[256];
77:     for (int i = 0; i < 256; i++) base64Value[i] = -1;
78:     for (int i = 0; i < 64; i++) base64Value[(int)base64Table[i]] = i;
79: 
80:     // Decode Base64 into binary data
81:     int len = base64Hash.length();
82:     int padding = (base64Hash[len - 1] == '=') + (base64Hash[len - 2] == '=');
83:     int binarySize = (len * 3) / 4 - padding;
84:     uint8_t binaryData[binarySize];
85: 
86:     int index = 0, buffer = 0, bits = 0;
87:     for (int i = 0; i < len; i++) {
88:         int value = base64Value[(int)base64Hash[i]];
89:         if (value == -1) continue;
90:         buffer = (buffer << 6) | value;
91:         bits += 6;
92:         if (bits >= 8) {
93:             bits -= 8;
94:             binaryData[index++] = (buffer >> bits) & 0xFF;
95:         }
96:     }
97: 
98:     // Convert binary data to hex string
