"void Logger::waitForSerial(uint32_t timeout_ms) {
#ifndef NATIVE_BUILD
    #ifndef BOARD_LED
      #ifdef LED_BUILTIN
        #define BOARD_LED LED_BUILTIN
      #else
        #define BOARD_LED 2
      #endif
    #endif

    BoardLED led(BOARD_LED);
    led.begin();
    uint32_t startAt = millis(); ///< Starting timestamp
    uint32_t lastFlip = 0;        ///< LED flip timestamp tracker
    uint32_t lastPrint = 0;       ///< Console print timestamp tracker

    while ((millis() - startAt) < timeout_ms) {
        uint32_t now = millis();
        uint32_t currentInterval = Serial ? 500 : 100;

        // LED flash state transition
        if ((now - lastFlip) >= currentInterval) {
            led.toggle();
            lastFlip = now;
        }

        // Periodic terminal trace (every 1 second)
        if ((now - lastPrint) >= 1000) {
            Serial.print(Serial ? "o" : ".");
            lastPrint = now;
        }

        delay(50); // Small yield to prevent watchdog trigger
    }

    if (Serial) {
        Serial.println();
    }
    led.off();
#else
    (void)timeout_ms;
#endif
}"

